import voice from '../data/engineVoice.json';

// Every beat of the engine story is timed from the voice-over phrases (src/data/engineVoice.json,
// generated by tools/align_voice.py), so re-aligning the voice moves the animation with it.
export type Phrase = {id: string; text: string; start: number; end: number; words: number[]};
export const PHRASES: Phrase[] = voice.phrases;
export const VOICE_SECONDS = voice.duration;

const byId = new Map(PHRASES.map((p) => [p.id, p]));
export const at = (id: string) => {
  const p = byId.get(id);
  if (!p) throw new Error(`Unknown phrase "${id}"`);
  return p.start;
};
export const endOf = (id: string) => byId.get(id)!.end;

export const clamp01 = (x: number) => Math.min(1, Math.max(0, x));
export const smooth = (x: number) => {
  const c = clamp01(x);
  return c * c * (3 - 2 * c);
};
// 0 → 1 over [t0, t0 + dur]
export const ramp = (t: number, t0: number, dur = 0.6) => smooth((t - t0) / dur);
// 0 → 1 → 0: in at t0, out at t1
export const window = (t: number, t0: number, t1: number, fade = 0.35) =>
  Math.min(ramp(t, t0, fade), 1 - ramp(t, t1 - fade, fade));

// ---------------- crank angle ----------------
// θ = 0 is top dead centre. Four strokes over 4π: intake 0..π, compression π..2π, power 2π..3π, exhaust 3π..4π.
type Seg = {t: number; kind: 'hold'} | {t: number; kind: 'to'; turns: number} | {t: number; kind: 'spin'; rps: number};
const PI = Math.PI;

// `to` eases to an absolute angle (in half turns, i.e. units of π) by the next segment's start.
const SEGMENTS: Seg[] = [
  {t: 0, kind: 'hold'},
  {t: at('updown'), kind: 'spin', rps: 0.45},
  {t: at('closed'), kind: 'to', turns: 4},
  {t: at('hole'), kind: 'hold'},
  {t: at('push') + 0.25, kind: 'to', turns: 5}, // blast pushes the piston down
  {t: at('push') + 0.9, kind: 'hold'}, // no flywheel: it stays at the bottom
  {t: at('inertia'), kind: 'spin', rps: 0.6},
  {t: at('nooxy'), kind: 'to', turns: 20}, // runs down to a stop at the top
  {t: at('nofire') + 1, kind: 'hold'},
  {t: at('mix'), kind: 'to', turns: 22}, // intake + compression
  {t: at('burn') + 0.2, kind: 'to', turns: 23}, // power
  {t: at('burn') + 0.9, kind: 'hold'},
  {t: at('trapped'), kind: 'to', turns: 24}, // up, exhaust trapped
  {t: at('block'), kind: 'to', turns: 25}, // down, little fresh mix gets in
  {t: at('stall'), kind: 'to', turns: 26},
  {t: endOf('stall'), kind: 'hold'},
  {t: at('out'), kind: 'to', turns: 28}, // exhaust valve lets it out
  {t: at('manual'), kind: 'spin', rps: 0.35},
  {t: at('cams'), kind: 'to', turns: 36},
  {t: at('rotate'), kind: 'spin', rps: 0.5},
  {t: at('sync'), kind: 'spin', rps: 1.2},
  {t: at('s1') - 0.4, kind: 'to', turns: 76}, // settle at TDC before the walkthrough
  {t: at('s1'), kind: 'to', turns: 77}, // intake
  {t: endOf('s1b'), kind: 'hold'},
  {t: at('s2'), kind: 'to', turns: 78}, // compression
  {t: endOf('s2b'), kind: 'hold'},
  {t: at('s3b'), kind: 'to', turns: 79}, // power
  {t: endOf('s3b'), kind: 'hold'},
  {t: at('s4b'), kind: 'to', turns: 80}, // exhaust
  {t: endOf('s4b'), kind: 'spin', rps: 0.8},
  {t: at('done'), kind: 'spin', rps: 1.6},
  {t: VOICE_SECONDS + 10, kind: 'hold'},
];

// θ at t: segments are integrated in order. `to` targets are absolute; `spin` adds rps · dt.
// Targets below the current angle are lifted by whole cycles (4π) so the crank never turns backwards.
const thetaTable = (() => {
  const starts: number[] = [];
  let theta = 0;
  for (let i = 0; i < SEGMENTS.length; i++) {
    starts.push(theta);
    const s = SEGMENTS[i];
    const next = SEGMENTS[i + 1];
    if (!next) break;
    if (s.kind === 'spin') theta += s.rps * 2 * PI * (next.t - s.t);
    if (s.kind === 'to') theta = target(theta, s.turns);
  }
  return starts;
})();

function target(from: number, turns: number) {
  let goal = turns * PI;
  while (goal < from - 1e-6) goal += 4 * PI;
  return goal;
}

export function crankAngle(t: number): number {
  let i = 0;
  while (i + 1 < SEGMENTS.length && SEGMENTS[i + 1].t <= t) i++;
  const s = SEGMENTS[i];
  const next = SEGMENTS[i + 1];
  const theta0 = thetaTable[i];
  if (s.kind === 'hold' || !next) return theta0;
  const u = (t - s.t) / (next.t - s.t);
  if (s.kind === 'spin') return theta0 + s.rps * 2 * PI * (t - s.t);
  const goal = target(theta0, s.turns);
  return theta0 + (goal - theta0) * smooth(u);
}

// ---------------- geometry of the moving parts ----------------
export const G = {
  bore: 1.0, // cylinder radius
  capY: 1.0, // underside of the head
  capTop: 1.13,
  cylBottom: -1.45,
  crankY: -2.25,
  crankR: 0.5,
  rodL: 1.85,
  pistonH: 0.85,
  pinToTop: 0.5, // piston pin to crown
  valveX: 0.56,
  stemTop: 2.2,
  camBase: 0.17,
  camLift: 0.14,
  flywheelR: 1.25,
  flywheelZ: -1.05,
  groundY: -3.6,
};

export function pistonPinY(theta: number) {
  const {crankR: r, rodL: l, crankY} = G;
  return crankY + r * Math.cos(theta) + Math.sqrt(l * l - r * r * Math.sin(theta) ** 2);
}
export const crankPin = (theta: number): [number, number] => [G.crankR * Math.sin(theta), G.crankY + G.crankR * Math.cos(theta)];

// stroke 0..3 = intake, compression, power, exhaust; f = progress within the stroke
export function stroke(theta: number) {
  const phi = ((theta % (4 * PI)) + 4 * PI) % (4 * PI);
  const k = Math.floor(phi / PI);
  return {k, f: phi / PI - k, phi};
}

// cam lobe: lift as a function of the cam's rotation away from its peak
export function lobeLift(d: number) {
  const w = ((d + PI) % (2 * PI) + 2 * PI) % (2 * PI) - PI; // wrap to -π..π
  const half = PI / 3;
  return Math.abs(w) < half ? G.camLift * Math.cos((w / half) * (PI / 2)) ** 2 : 0;
}
// cams turn at half crank speed; intake peaks mid-intake (φ = π/2), exhaust mid-exhaust (φ = 3.5π)
export const CAM_PEAK = {intake: PI / 4, exhaust: 1.75 * PI};
export const camAngle = (theta: number) => theta / 2;
